      { x: 240, y: 150, r: 340, color: 'rgba(27,42,107,0.55)' },
      { x: 1060, y: 560, r: 380, color: 'rgba(75,27,107,0.5)' },
      { x: 980, y: 110, r: 260, color: 'rgba(20,80,110,0.4)' },
      { x: 180, y: 600, r: 240, color: 'rgba(107,27,80,0.35)' },
